public class Main {
    // multiply pairs, add up
    static double dot(double[] a, double[] b) {
        double s = 0;
        for (int i = 0; i < a.length; i++) s += a[i] * b[i];
        return s;
    }

    // divide by both lengths: only direction is left
    static double cosine(double[] a, double[] b) {
        return dot(a, b) / (Math.sqrt(dot(a, a)) * Math.sqrt(dot(b, b)));
    }

    public static void main(String[] args) {
        double[] a = {1, 2, 3};
        double[] b = {2, 4, 6}; // same direction as a, twice as long
        double[] c = {3, 2, 1};
        System.out.println("a = [1, 2, 3] b = [2, 4, 6] c = [3, 2, 1]");
        System.out.println(String.format("dot(a,b) = %d  cosine = %.4f", (int) dot(a, b), cosine(a, b)));
        System.out.println(String.format("dot(a,c) = %d  cosine = %.4f", (int) dot(a, c), cosine(a, c)));
        // normalise once, then a plain dot product equals cosine
        double na = Math.sqrt(dot(a, a)), nc = Math.sqrt(dot(c, c));
        double[] ua = new double[3], uc = new double[3];
        for (int i = 0; i < 3; i++) { ua[i] = a[i] / na; uc[i] = c[i] / nc; }
        System.out.println(String.format("unit dot(a,c) = %.4f", dot(ua, uc)));
        // Time O(d) per pair, space O(d)
    }
}

