import java.util.*;

public class Main {
    static int[][] matmul(int[][] A, int[][] B) {
        int n = A.length, k = A[0].length, k2 = B.length, m = B[0].length;
        if (k != k2) return null; // inner sizes must match
        int[][] R = new int[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                for (int t = 0; t < k; t++)
                    R[i][j] += A[i][t] * B[t][j]; // row i of A dot column j of B
        return R;
    }

    static String show(int[][] r) {
        if (r == null) return "None";
        List<String> rows = new ArrayList<>();
        for (int[] row : r) rows.add(Arrays.toString(row));
        return "[" + String.join(", ", rows) + "]";
    }

    public static void main(String[] args) {
        int[][] A = {{1, 2, 3}, {4, 5, 6}};          // 2x3
        int[][] B = {{7, 8}, {9, 10}, {11, 12}};     // 3x2
        System.out.println("A (2x3) @ B (3x2) = " + show(matmul(A, B)));  // 2x2
        System.out.println("B (3x2) @ A (2x3) = " + show(matmul(B, A)));  // 3x3: order matters
        System.out.println("A (2x3) @ A (2x3) = " + show(matmul(A, A)));  // None: 3 != 2
        // Time O(n*k*m), space O(n*m)
    }
}

