#include <bits/stdc++.h>
using namespace std;
typedef vector<vector<int>> Mat;

bool matmul(const Mat& A, const Mat& B, Mat& R) {
    size_t n = A.size(), k = A[0].size(), m = B[0].size();
    if (k != B.size()) return false;  // inner sizes must match
    R.assign(n, vector<int>(m, 0));
    for (size_t i = 0; i < n; i++)
        for (size_t j = 0; j < m; j++)
            for (size_t t = 0; t < k; t++)
                R[i][j] += A[i][t] * B[t][j];  // row i of A dot column j of B
    return true;
}

void show(const string& label, const Mat& A, const Mat& B) {
    Mat R;
    cout << label << " = ";
    if (!matmul(A, B, R)) { cout << "None\n"; return; }
    cout << "[";
    for (size_t i = 0; i < R.size(); i++) {
        cout << (i ? ", [" : "[");
        for (size_t j = 0; j < R[i].size(); j++) cout << (j ? ", " : "") << R[i][j];
        cout << "]";
    }
    cout << "]\n";
}

int main() {
    Mat A = {{1, 2, 3}, {4, 5, 6}};          // 2x3
    Mat B = {{7, 8}, {9, 10}, {11, 12}};     // 3x2
    show("A (2x3) @ B (3x2)", A, B);  // 2x2
    show("B (3x2) @ A (2x3)", B, A);  // 3x3: order matters
    show("A (2x3) @ A (2x3)", A, A);  // None: 3 != 2
    // Time O(n*k*m), space O(n*m)
}

