public class Main {
    static double[] mul(double[][] M, double[] v) {
        double[] r = new double[v.length];
        for (int i = 0; i < M.length; i++)
            for (int j = 0; j < v.length; j++) r[i] += M[i][j] * v[j];
        return r;
    }

    public static void main(String[] args) {
        double[][] M = {{2, 1}, {1, 2}}; // eigenvalues 3 and 1; dominant direction [1, 1]
        double[] v = {1, 0};             // arbitrary start with some part along the top direction
        for (int step = 0; step < 20; step++) {
            double[] w = mul(M, v);                      // apply the matrix
            double norm = Math.sqrt(w[0] * w[0] + w[1] * w[1]);
            for (int i = 0; i < 2; i++) v[i] = w[i] / norm; // rescale to length 1
        }
        double[] Mv = mul(M, v);
        double lam = (v[0] * Mv[0] + v[1] * Mv[1]) / (v[0] * v[0] + v[1] * v[1]); // Rayleigh quotient
        System.out.println("matrix = [[2, 1], [1, 2]]");
        System.out.println(String.format("eigenvalue = %.4f", lam));
        System.out.println(String.format("eigenvector = [%.4f, %.4f]", v[0], v[1]));
        // Time O(steps * n^2) dense, space O(n)
    }
}

